Here's a simple JavaScript function that iterates through an array of 5 numbers, checks if any of them is a prime number, and prints the prime number(s) to the console:

```javascript
function isPrime(num) {
  if (num <= 1) return false;
  if (num <= 3) return true;

  if (num % 2 === 0 || num % 3 === 0) return false;

  for (let i = 5; i * i <= num; i += 6) {
    if (num % i === 0 || num % (i + 2) === 0) return false;
  }

  return true;
}

function checkPrimesInArray(numbersArray) {
  if (numbersArray.length !== 5) {
    console.error('The array must contain exactly 5 numbers.');
    return;
  }

  numbersArray.forEach(number => {
    if (isPrime(number)) {
      console.log(number);
    }
  });
}

